def S(n):
    """Calculates the sum of the digits of n."""
    return sum(int(digit) for digit in str(n))

def check_hypothesis(limit=10000):
    """
    Checks if S(n+i) < 11 for all i in {0, ..., 37}.
    Returns the smallest such n found within the limit, or None if not found.
    """
    print("--- Starting search for smallest n such that S(n+i) < 11 for i=0..37 ---")

    found_n = None
    for n in range(1, limit + 1):
        is_sufficient = True
        for i in range(38):
            current_sum = S(n + i)
            if current_sum >= 11:
                is_sufficient = False
                break

        if is_sufficient:
            found_n = n
            break

    if found_n is not None:
        print(f"\nSUCCESS: Smallest n found satisfying the strict hypothesis (S(n+i) < 11): n = {found_n}")
        return found_n
    else:
        print(f"\nFAILURE: No such n found up to the limit {limit}. (Note: Max n where S(n+37)<11 is theoretically unbounded.)")
        return None

# Execute the check
result = check_hypothesis()
print(f"Result returned by script: {result}")

